// =============================================================================
// Al-Taqwa web — push notification service worker (Firebase Cloud Messaging).
//
// Firebase registers this file itself (scope /firebase-cloud-messaging-push-scope)
// when the app asks for a push token. It shows each notification the server
// sends — Arabic, right-to-left, with the app icon (backend firebase.service.ts
// WEB_PUSH) — and opens or focuses the app when one is tapped.
//
// Everything is loaded from this origin: the settings (/firebase-config.js,
// generated by the server) and the vendored Firebase SDK (vendor/firebase/).
// It caches nothing and never handles fetches, so it cannot serve stale pages.
// =============================================================================

'use strict';

// Ours first, so it runs before Firebase's own click handler.
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil((async () => {
    const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const client of windows) {
      if (new URL(client.url).origin === self.location.origin && 'focus' in client) {
        return client.focus();
      }
    }
    return self.clients.openWindow('/');
  })());
});

importScripts('/firebase-config.js');

if (self.TAQWA_FIREBASE_CONFIG) {
  importScripts(
    '/vendor/firebase/firebase-app-compat.js',
    '/vendor/firebase/firebase-messaging-compat.js'
  );
  const { vapidKey, ...options } = self.TAQWA_FIREBASE_CONFIG;
  firebase.initializeApp(options);
  // With a `notification` payload the SDK displays the message by itself.
  firebase.messaging();
}
